# v108: „Katasztrófák Rómában: tűz, árvíz, földrengés” kártya (hu/en). Adat: dis/data.py
import sys;sys.path.insert(0,'dis');import data as D
LAB={'victoria':('Victoria temploma','Temple of Victoria'),'metasudans':('Meta Sudans','Meta Sudans'),'titus':('Titus íve','Arch of Titus'),'saturn':('Saturnus temploma','Temple of Saturn'),'comitium':('Comitium','Comitium'),'vesta':('Vesta temploma','Temple of Vesta'),'portacarm':('Porta Carmentalis','Porta Carmentalis'),'spes':('Spes temploma','Temple of Spes'),'omobono':('Sant’Omobono (Fortuna és Mater Matuta)','Sant’Omobono (Fortuna and Mater Matuta)'),'regia':('Regia','Regia'),'magnamater':('Magna Mater temploma','Temple of Magna Mater'),'iovis':('Iuppiter Optimus Maximus temploma','Temple of Jupiter Optimus Maximus'),'hostilia':('Curia Hostilia','Curia Hostilia'),'porcia':('Basilica Porcia','Basilica Porcia'),'quirinus':('Quirinus temploma','Temple of Quirinus'),'circusmax':('Circus Maximus','Circus Maximus'),'aemilia':('Basilica Aemilia','Basilica Aemilia'),'castor':('Castor temploma','Temple of Castor'),'julia':('Basilica Iulia','Basilica Iulia'),'casaromuli':('Romulus kunyhói','Huts of Romulus'),'theatrumpompei':('Pompeius színháza','Theatre of Pompey'),'vestals':('Atrium Vestae','Atrium Vestae'),'pantheon':('Pantheon','Pantheon'),'saepta':('Saepta Iulia','Saepta Iulia'),'pacis':('a Béke temploma','Temple of Peace'),'horreapiper':('Horrea Piperataria','Horrea Piperataria'),'apollo':('Apollón Palatinus temploma','Temple of Apollo Palatinus'),'curiapompei':('Pompeius curiája','Curia of Pompey')}
def cen(y): return (y//100)*100 if y>=0 else -((-y-1)//100+1)*100
def build(l):
    H=l=='hu';T=lambda h,e:h if H else e
    def yl(y): return (f'Kr. e. {-y}' if y<0 else f'Kr. u. {y}') if H else (f'{-y} BC' if y<0 else f'AD {y}')
    def cl(a):
        n=abs(a)//100+(1 if a>=0 else 0)
        if H: return (f'Kr. e. {n}. század' if a<0 else f'Kr. u. {n}. század')
        o={1:'1st',2:'2nd',3:'3rd'}.get(n,f'{n}th');return (f'{o} century BC' if a<0 else f'{o} century AD')
    d1=lambda x:(str(x).replace('.',',') if H else str(x))
    o=[]
    o.append('    <section class="card" id="discard">')
    o.append('      <h2>'+T('Katasztrófák Rómában: tűz, árvíz, földrengés','Disasters in Rome: fire, flood, earthquake')+'</h2>')
    o.append('      <p class="hint">'+T('Az ókori szerzők három visszatérő csapást jegyeztek fel a városról: a tűzvészeket, a Tiberis áradásait és a földrengéseket. A kártya három modern gyűjtés adatait teszi egy idővonalra: %d név szerint leírt tűzvész, %d árvíz és %d Rómára helyezett földrengés. A tűzvészeknél a leégett épületek neve a térképre ugrik.'%(len(D.FIRES),len(D.FLOODS)+len(D.FLOODR),len(D.QUAKES)),'Ancient authors recorded three recurring calamities of the city: fires, the floods of the Tiber and earthquakes. The card puts the data of three modern collections on one timeline: %d individually described fires, %d floods and %d earthquakes located at Rome. For the fires, the names of the burnt buildings jump to the map.'%(len(D.FIRES),len(D.FLOODS)+len(D.FLOODR),len(D.QUAKES)))+'</p>')
    X0,X1=-500,650;Wd,Ht,L,R,Tp=860,230,110,12,14;pw=Wd-L-R;rows=[52,104,156];base=186
    xx=lambda y:L+(y-X0)/(X1-X0)*pw
    s=['      <svg class="dissvg" viewBox="0 0 %d %d" role="img" aria-label="%s">'%(Wd,Ht,T('Tűzvészek, árvizek és földrengések Rómában Kr. e. 500 és Kr. u. 650 között','Fires, floods and earthquakes in Rome between 500 BC and AD 650'))]
    for y in range(-500,651,100): s.append('<line class="gr" x1="%.1f" x2="%.1f" y1="%d" y2="%d"/>'%(xx(y),xx(y),Tp,base))
    for r,(h,e) in zip(rows,[('tűzvész','fire'),('árvíz','flood'),('földrengés','earthquake')]): s.append('<text class="ax rl" x="%d" y="%d" text-anchor="end">%s</text><line class="bl" x1="%d" x2="%d" y1="%d" y2="%d"/>'%(L-10,r+5,T(h,e),L,Wd-R,r+18,r+18))
    for y,w,hu,en,ids in D.FIRES: s.append('<rect class="fi%d" data-fy="%d" x="%.1f" y="%d" width="%d" height="%d"><title>%s: %s</title></rect>'%(w,y,xx(y)-(3 if w else 2.5),rows[0]+18-(34 if w else 18),6 if w else 5,34 if w else 18,yl(y),T(hu,en).replace('"','')))
    for y in D.FLOODS: s.append('<rect class="fl" x="%.1f" y="%d" width="3" height="24"><title>%s</title></rect>'%(xx(y)-1.5,rows[1]-6,yl(y)))
    for a,b,n in D.FLOODR: s.append('<rect class="flr" x="%.1f" y="%d" width="%.1f" height="8"><title>%s (%d–%d)</title></rect>'%(xx(a),rows[1]+10,max(3,xx(b)-xx(a)),n,a,b))
    for y,io,q in D.QUAKES:
        big=io is not None and io>=7
        s.append('<circle class="qk%d" cx="%.1f" cy="%d" r="%d"><title>%s%s%s</title></circle>'%(1 if big else 0,xx(y),rows[2]+(2 if big else 8),8 if big else 4,yl(y),'?' if q else '',(' – Io '+d1(io)) if io is not None else ''))
    for y in range(-400,601,200): s.append('<text class="ax" x="%.1f" y="%d" text-anchor="middle">%s</text>'%(xx(y),base+22,yl(y)))
    s.append('</svg>');o.append(''.join(s))
    o.append('      <p class="hint aqleg"><span class="sw dfi1"></span> '+T('kiterjedt tűzvész · ','widespread fire · ')+'<span class="sw dfi0"></span> '+T('egy-két épület tüze · ','fire of one or two buildings · ')+'<span class="sw dfl"></span> '+T('árvíz (a fekvő sáv: csak uralkodásra keltezve) · ','flood (horizontal bar: dated only to a reign) · ')+'<span class="sw dqk"></span> '+T('földrengés; a nagy kör legalább VII-es erősségű (MCS-skála)','earthquake; the large circle is of intensity VII or more (MCS scale)')+'</p>')
    o.append('      <p class="hint disstat" id="disstat" hidden><b></b> <span class="dn" hidden>'+T('{y}: {n} leégett épület kiemelve a térképen.','{y}: {n} burnt buildings highlighted on the map.')+'</span><span class="dz" hidden>'+T('{y}: ennek a tűznek nincs azonosítható épülete a térképen.','{y}: this fire has no identifiable building on the map.')+'</span> <button class="chip" id="disclr">'+T('Kiemelés törlése','Clear highlight')+'</button></p>')
    o.append('      <p class="hint">'+T('<b>Kattints egy tűzvész jelére az idővonalon, vagy az évszámára a lenti táblázatban:</b> a térkép évcsúszkája arra az évre áll, a leégett épületek pedig pirossal kiemelve jelennek meg. Ugyanez történik, ha a csúszkát kézzel állítod egy tűzvész évére.','<b>Click a fire mark on the timeline, or its year in the table below:</b> the year slider of the map moves to that year and the burnt buildings appear highlighted in red. The same happens if you move the slider by hand to the year of a fire.')+'</p>')
    SRC=T('tűz: H. V. Canter, „Conflagrations in Ancient Rome”, <i>Classical Journal</i> 27 (1932) 270–288; árvíz: G. S. Aldrete, <i>Floods of the Tiber in Ancient Rome</i> (2007) jegyzéke az ókori szerzők alapján; földrengés: E. Guidoboni és társai, <i>CFTI5Med</i>, INGV 2018 (CC BY 4.0).','fire: H. V. Canter, “Conflagrations in Ancient Rome”, <i>Classical Journal</i> 27 (1932) 270–288; flood: the list of G. S. Aldrete, <i>Floods of the Tiber in Ancient Rome</i> (2007), from the ancient authors; earthquake: E. Guidoboni et al., <i>CFTI5Med</i>, INGV 2018 (CC BY 4.0).')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+'</p>')
    o.append('      <p class="hint">'+T('<b>Az idővonal a forrásokat is mutatja, nem csak az eseményeket.</b> Az árvizek két csomóban sűrűsödnek: Kr. e. 215 és 189 között, ahonnan Livius könyvei fennmaradtak, és Kr. e. 60 és Kr. u. 36 között, amelyet Cassius Dio részletesen elbeszél. Kr. e. 156 és 60 között egyetlen árvízről sincs adat: erre az időre nincs folyamatos elbeszélő forrásunk, a Tiberis ettől még áradhatott.','<b>The timeline shows the sources as well as the events.</b> The floods cluster in two groups: between 215 and 189 BC, for which the books of Livy survive, and between 60 BC and AD 36, which Cassius Dio narrates in detail. Between 156 and 60 BC not a single flood is recorded: for this period we have no continuous narrative source, and the Tiber may well have flooded all the same.')+'</p>')
    # századonkénti tábla
    C={}
    for y,*_ in D.FIRES: C.setdefault(cen(y),[0,0,0])[0]+=1
    for y in D.FLOODS: C.setdefault(cen(y),[0,0,0])[1]+=1
    for a,b,n in D.FLOODR: C.setdefault(cen((a+b)//2),[0,0,0])[1]+=1
    for y,io,q in D.QUAKES: C.setdefault(cen(y),[0,0,0])[2]+=1
    o.append('      <div class="regwrap"><table class="regtab distab">')
    o.append('        <thead><tr><th>'+T('Század','Century')+'</th><th>'+T('Tűzvész','Fires')+'</th><th>'+T('Árvíz','Floods')+'</th><th>'+T('Földrengés','Earthquakes')+'</th></tr></thead>')
    o.append('        <tbody>')
    for a in range(-500,700,100):
        v=C.get(a,[0,0,0]);o.append('          <tr><td>'+cl(a)+'</td><td>%d</td><td>%d</td><td>%d</td></tr>'%tuple(v))
    o.append('        </tbody>')
    o.append('        <tfoot><tr><td>'+T('Együtt','Total')+'</td><td>%d</td><td>%d</td><td>%d</td></tr></tfoot>'%(len(D.FIRES),len(D.FLOODS)+len(D.FLOODR),len(D.QUAKES)))
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+SRC+' '+T('Saját összesítés.','Own tabulation.')+'</p>')
    o.append('      <h3 class="aqh">'+T('Tűzvészek','Fires')+'</h3>')
    o.append('      <p class="hint">'+T('Canter a köztársaság korából tizenöt megbízhatóan feljegyzett tüzet számol, a császárkorból (Kr. e. 31 – Kr. u. 425 körül) negyvennégy nagy tűzvészt; az alábbi lista azokat tartalmazza, amelyeket név szerint le is ír. Szerinte a köztársaság kori tüzek két szűk területre estek: a Tiberis-parti ipari és kereskedőnegyedre és a Forum környékére.','Canter counts fifteen reliably recorded fires for the Republic and forty-four major fires for the imperial period (31 BC to about AD 425); the list below contains those he describes individually. According to him the Republican fires fell in two limited areas: the industrial and commercial quarter along the Tiber and the surroundings of the Forum.')+'</p>')
    o.append('      <div class="regwrap"><table class="regtab aniotab distab2">')
    o.append('        <thead><tr><th>'+T('Év','Year')+'</th><th>'+T('Mi égett le','What burned')+'</th><th>'+T('A térképen','On the map')+'</th></tr></thead>')
    o.append('        <tbody>')
    for y,w,hu,en,ids in D.FIRES:
        seen=[];[seen.append(i) for i in ids if i not in seen]
        lk=' · '.join('<a href="#" data-go="%s">%s</a>'%(i,LAB[i][0 if H else 1]) for i in seen)
        o.append('          <tr%s data-fy="%d"><td><button class="chip fgo">%s</button></td><td>%s</td><td>%s</td></tr>'%(' class="big"' if w else '',y,yl(y),T(hu,en),lk))
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('H. V. Canter, „Conflagrations in Ancient Rome”, <i>Classical Journal</i> 27 (1932) 270–288 (közkincs; a szöveg a LacusCurtius oldalon); az évszámok és a leírások az ő elbeszélését követik. A vastag sorok a kiterjedt tűzvészek.','H. V. Canter, “Conflagrations in Ancient Rome”, <i>Classical Journal</i> 27 (1932) 270–288 (public domain; text on LacusCurtius); dates and descriptions follow his account. Bold rows are the widespread fires.')+'</p>')
    o.append('      <h4 class="aqh4">'+T('A császárkor 44 nagy tüze kerületenként','The 44 major fires of the imperial period by region')+'</h4>')
    mx=max(n for _,n in D.FREG)
    o.append('      <div class="disbars">'+''.join('<div class="dbr"><span class="dbl">%s</span><span class="dbb" style="width:%.1f%%"></span><span class="dbn">%d</span></div>'%(r,100*n/mx*0.8,n) for r,n in D.FREG)+'</div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('Canter 1932, 278. o.; egy tűz több kerületet is érinthetett, ezért az összeg több mint 44.','Canter 1932, p. 278; one fire could affect several regions, so the sum exceeds 44.')+'</p>')
    o.append('      <p class="hint">'+T('A kerületi említések hatvan százaléka (51-ből 31) a város közepére esik: a VIII. (Forum Romanum, császári fórumok, Capitolium), a IX. (Circus Flaminius és Campus Martius) és a X. kerületre (Palatium). A két szélső kerületből, az I.-ből (Porta Capena) és a XIV.-ből (Transtiberim) egyetlen nagy tűzről sincs adat. Ez részben forráshatás: a szerzők a nagy középületek pusztulását jegyezték fel, a külső lakónegyedekét ritkán. Vesta temploma ötször, a Regia és Pompeius színháza legalább négyszer égett le.','Sixty per cent of the regional mentions (31 of 51) fall in the centre of the city: in Regions VIII (Forum Romanum, imperial fora, Capitoline), IX (Circus Flaminius and Campus Martius) and X (Palatium). From the two outermost regions, I (Porta Capena) and XIV (Transtiberim), no major fire is recorded at all. This is partly a source effect: authors recorded the destruction of great public buildings, rarely that of outlying residential quarters. The temple of Vesta burned five times, the Regia and the theatre of Pompey at least four times.')+'</p>')
    o.append('      <h4 class="aqh4">'+T('Régészeti nyomok: a tűz a SITAR ásatási adataiban','Archaeological traces: fire in the SITAR excavation records')+'</h4>')
    o.append('      <p class="hint">'+T('A térkép SITAR-rétegének %d ásatási egységéből 10 tűzvésznél van olyan, amelynek leírása az építési fázist név szerint ismert tűzhöz köti: a leégés utáni újjáépítés, betemetés vagy helyreállítás nyoma a földben. Kilenc egyezik a fenti listával, egy (Kr. u. 50 körül) csak régészetileg ismert.'%6197,'Of the %d excavation units in the map’s SITAR layer, there are records for 10 fires whose description links a building phase to a fire known by date: traces in the ground of rebuilding, burial or restoration after the fire. Nine match the list above; one (c. AD 50) is known only from archaeology.'%6197)+'</p>')
    o.append('      <div class="regwrap"><table class="regtab aniotab distab2">')
    o.append('        <thead><tr><th>'+T('Tűz','Fire')+'</th><th>'+T('Mit mutat az ásatás','What the excavation shows')+'</th><th>'+T('A térképen','On the map')+'</th></tr></thead>')
    o.append('        <tbody>')
    for y,yh,ye,hu,en,ids in D.SITF:
        lk=' · '.join('<a href="#" data-go="%s">%s</a>'%(i,LAB[i][0 if H else 1]) for i in ids)
        o.append('          <tr><td>%s</td><td>%s</td><td>%s</td></tr>'%(T(yh,ye),T(hu,en),lk))
    o.append('        </tbody>')
    o.append('      </table></div>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('SITAR – Sistema Informativo Territoriale Archeologico di Roma, Soprintendenza Speciale di Roma (CC BY-SA 4.0), a térkép SITAR-rétegének egységleírásai; saját kigyűjtés és összefoglalás. Csak az a tűz szerepel, amelyet a leírás évszámmal vagy uralkodóval megnevez; a „talán” jelzésű utalások közül egy (Kr. u. 64, Clivus Vestae) került be.','SITAR – Sistema Informativo Territoriale Archeologico di Roma, Soprintendenza Speciale di Roma (CC BY-SA 4.0), unit descriptions of the map’s SITAR layer; own selection and summary. Only fires named by year or ruler in the record are included; of the references marked “probably”, one (AD 64, Clivus Vestae) is included.')+'</p>')
    o.append('      <h3 class="aqh">'+T('A Tiberis árvizei','Floods of the Tiber')+'</h3>')
    fl=lambda a,b:', '.join((str(-y) if y<0 else str(y)) for y in D.FLOODS if a<=y<b)
    o.append('      <p class="hint">'+T('Kr. e. 414 és Kr. u. 398 között 33 árvízről tudunk. <b>Kr. e.:</b> %s. <b>Kr. u.:</b> %s; ezenkívül egy-egy Nerva (96–98), Traianus (98–117) és Hadrianus (117–138) alatt, pontos év nélkül.'%(fl(-500,0),fl(0,700)),'Between 414 BC and AD 398 we know of 33 floods. <b>BC:</b> %s. <b>AD:</b> %s; in addition one each under Nerva (96–98), Trajan (98–117) and Hadrian (117–138), without an exact year.'%(fl(-500,0),fl(0,700)))+'</p>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('G. S. Aldrete, <i>Floods of the Tiber in Ancient Rome</i>, Baltimore 2007, jegyzéke; az ókori források: Livius, Cassius Dio, Tacitus, Plutarkhosz, Horatius, ifjabb Plinius, Historia Augusta, Aurelius Victor, Ammianus Marcellinus, Claudianus.','the list of G. S. Aldrete, <i>Floods of the Tiber in Ancient Rome</i>, Baltimore 2007; ancient sources: Livy, Cassius Dio, Tacitus, Plutarch, Horace, Pliny the Younger, Historia Augusta, Aurelius Victor, Ammianus Marcellinus, Claudian.')+'</p>')
    o.append('      <p class="hint">'+T('Az árvíz a város mély fekvésű részeit érte: a Campus Martiust, a Forum Boarium és a Velabrum környékét, a Circus Maximus völgyét. A „Mai domborzat” réteggel a térképen is látszik, mely részek fekszenek alacsonyan, de a mai felszín a völgyekben 5–15 méterrel magasabb az ókorinál, ezért az elöntött terület ebből nem rajzolható meg pontosan.','The floods reached the low-lying parts of the city: the Campus Martius, the area of the Forum Boarium and the Velabrum, the valley of the Circus Maximus. The “Present-day relief” layer shows on the map which parts lie low, but in the valleys the present surface is 5–15 metres higher than the ancient one, so the flooded area cannot be drawn from it precisely.')+'</p>')
    o.append('      <h3 class="aqh">'+T('Földrengések','Earthquakes')+'</h3>')
    big=[(y,io) for y,io,q in D.QUAKES if io is not None and io>=7]
    o.append('      <p class="hint">'+T('Az olasz földrengés-katalógus Kr. e. 461 és Kr. u. 618 között %d rengést helyez Rómára; ezek az ókori szerzők híradásain alapulnak. Hat érte el a VII–VIII-as erősséget, amelynél már épületek sérülnek: %s. A többi, ahol az erősség ismert, IV–VI-os: érezhető, de károkat alig okozó rengés. %d esetben a katalógus maga is kérdőjelesnek jelöli, hogy a rengés Rómában volt-e.'%(len(D.QUAKES),', '.join(yl(y)+' ('+d1(io)+')' for y,io in big),sum(q for _,_,q in D.QUAKES)),'The Italian earthquake catalogue places %d earthquakes at Rome between 461 BC and AD 618; they rest on the reports of ancient authors. Six reached intensity VII–VIII, at which buildings are damaged: %s. The rest, where the intensity is known, are of IV–VI: felt, but causing hardly any damage. In %d cases the catalogue itself marks as doubtful whether the earthquake was at Rome.'%(len(D.QUAKES),', '.join(yl(y)+' ('+d1(io)+')' for y,io in big),sum(q for _,_,q in D.QUAKES)))+'</p>')
    o.append('      <p class="hint srcl"><b>'+T('Forrás:','Source:')+'</b> '+T('E. Guidoboni, G. Ferrari, D. Mariotti, A. Comastri, G. Tarabusi, G. Sgattoni, G. Valensise, <i>CFTI5Med, Catalogo dei Forti Terremoti in Italia (461 a.C.–1997)</i>, INGV 2018, doi:10.6092/ingv.it-cfti5 (CC BY 4.0); a „Roma” epicentrumú rengések. Az erősség az epicentrális intenzitás (Io) a Mercalli–Cancani–Sieberg-skálán.','E. Guidoboni, G. Ferrari, D. Mariotti, A. Comastri, G. Tarabusi, G. Sgattoni, G. Valensise, <i>CFTI5Med, Catalogo dei Forti Terremoti in Italia (461 a.C.–1997)</i>, INGV 2018, doi:10.6092/ingv.it-cfti5 (CC BY 4.0); earthquakes with epicentre “Roma”. Intensity is epicentral intensity (Io) on the Mercalli–Cancani–Sieberg scale.')+'</p>')
    o.append('      <p class="hint">'+T('A három sor néhol egybeesik: Kr. e. 192-ben mindhárom csapás érte a várost, Kr. u. 5-ben, 15-ben és 217-ben ugyanabban az évben volt árvíz és földrengés, 191-ben földrengés és nagy tűzvész. Ennek egyik oka, hogy a római történetírók a rossz előjeleket együtt, egy-egy év végén sorolták fel, így ahol az egyik fennmaradt, ott gyakran a másik is. Canter szerint a nagy tüzek után a város rendre jobb minőségben épült újjá (vö. „Építkezések időrendben”).','The three rows sometimes coincide: in 192 BC all three calamities struck the city, in AD 5, 15 and 217 there was a flood and an earthquake in the same year, in 191 an earthquake and a great fire. One reason is that Roman historians listed bad omens together, at the end of a year, so where one survives the other often does too. According to Canter, after the great fires the city was regularly rebuilt to a better standard (cf. “Building activity over time”).')+'</p>')
    o.append('    </section>')
    return '\n'.join(o)+'\n'
SUB=('30 tűzvész, 33 árvíz és 25 földrengés egy idővonalon; a leégett épületek a térképen','30 fires, 33 floods and 25 earthquakes on one timeline; the burnt buildings on the map')
