def js():
    import json
    F={}
    for y,w,hu,en,ids in D.FIRES:
        F.setdefault(y,[])
        for i in ids:
            if i not in F[y]: F[y].append(i)
    return open('src/dis_hook.js',encoding='utf8').read().replace('__DISF__',json.dumps(F,separators=(',',':')))
